import{_ as o,c as i,o as s,a3 as t,j as e,a}from"./chunks/framework.BT-mtt1U.js";const f=JSON.parse(`{"title":"Our FAQs","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/FAQ'S.md","filePath":"wiki/FAQ'S.md","lastUpdated":null}`),n={name:"wiki/FAQ'S.md"};function l(d,r,h,c,u,m){return s(),i("div",null,r[0]||(r[0]=[t('<p><a href="https://sdmis.nios.ac.in/home/faqs" target="_blank" rel="noreferrer">Official FAQs (The offical ones are outdated)</a></p><h1 id="our-faqs" tabindex="-1">Our FAQs <a class="header-anchor" href="#our-faqs" aria-label="Permalink to &quot;Our FAQs&quot;">​</a></h1><p>Based on your Questions from Telegram, Discord, and Subreddit</p><p><strong>TMA and Admission FAQs</strong></p><h2 id="isn-t-the-marks-for-tma-20-more-than-the-maximum-theory-marks" tabindex="-1">Isn&#39;t the marks for TMA 20% more than the maximum theory marks? <a class="header-anchor" href="#isn-t-the-marks-for-tma-20-more-than-the-maximum-theory-marks" aria-label="Permalink to &quot;Isn&#39;t the marks for TMA 20% more than the maximum theory marks?&quot;">​</a></h2><p>Ans: For some who are wondering “wait, if we add this up, it would be 116 marks in total?! How so?”, well NIOS follows a bit different rule compared to other boards here. See the 16 marks assigned in TMA is added up <strong>by deducting 20% of marks from Public Examination, i.e. theory paper</strong> so for example if you scored 14 marks in your TMA and 60 marks in your public exam, 20% of the marks from public exams are cut 20% of 60 marks = 12 marks.</p><h2 id="why-does-tma-marks-shown-more-than-20-of-theory-marks" tabindex="-1">Why does TMA marks shown more than 20% of theory marks? <a class="header-anchor" href="#why-does-tma-marks-shown-more-than-20-of-theory-marks" aria-label="Permalink to &quot;Why does TMA marks shown more than 20% of theory marks?&quot;">​</a></h2><p>Ans: From October 2024 session, TMA evaluation pattern has been changed. As we know in Theory, full marks on Question Paper and on Marksheet remain different. (TMA marks are adjusted after calculation) So, 100 becomes 80, 80 becomes 64. Same will be followed for TMA now onwards. Earlier TMA marks was uploaded after calculating 20% of Theory marks. e.g. Home Science 216, on Dashboard full marks for TMA is 20 but on Marksheet it&#39;ll be calculated out of 17. If for same subject, Dashboard is showing 18 then take it as 18 out of 20 which will become on marksheet 15 out of 17 after calculation.</p><p>Table attached showing full TMA marks of all Subjects on Marksheet (20% of Theory Marks). Now you can calculate Actual TMA marks by yourself:</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>&#39;Theory&#39; refers to subjects without practical e.g. Social science and History</strong>. <a href="https://docs.google.com/document/d/1IkOCPBsEOd-owsX70-DvP0b5epAoJob3zEtI3OGJUMs/edit?usp=drive_link" target="_blank" rel="noreferrer">Sebject names with corresponding subject code</a></p></div><h2 id="_12th-senior-secondary" tabindex="-1">12th (Senior Secondary) <a class="header-anchor" href="#_12th-senior-secondary" aria-label="Permalink to &quot;12th (Senior Secondary)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Sub Code/Category</th><th>Max Marks on th QP</th><th>20% of Marks</th></tr></thead><tbody><tr><td>All Theory and Languages</td><td>80</td><td>20</td></tr><tr><td>312, 313, 314, 316, 321, 333, 339, 335 and 376</td><td>64</td><td>16</td></tr><tr><td>330</td><td>48</td><td>12</td></tr><tr><td>336</td><td>32</td><td>08</td></tr><tr><td>373</td><td>56</td><td>14</td></tr><tr><td>332</td><td>40</td><td>08</td></tr></tbody></table><hr><h2 id="_10th-secondary" tabindex="-1">10th (Secondary) <a class="header-anchor" href="#_10th-secondary" aria-label="Permalink to &quot;10th (Secondary)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Sub Code/Category</th><th>Max Marks on Th QP</th><th>20% i.e. Max Marks of TMA</th></tr></thead><tbody><tr><td>All Theory and Languages</td><td>80</td><td>20</td></tr><tr><td>212 and 216</td><td>68</td><td>17</td></tr><tr><td>225</td><td>24</td><td>06</td></tr><tr><td>229, 230, 242 and 243</td><td>32</td><td>08</td></tr></tbody></table><hr><h2 id="who-checks-my-tma-and-how-much-effort-do-put-in-it" tabindex="-1">Who checks my TMA and how much effort do put in it? <a class="header-anchor" href="#who-checks-my-tma-and-how-much-effort-do-put-in-it" aria-label="Permalink to &quot;Who checks my TMA and how much effort do put in it?&quot;">​</a></h2><p>Ans: The teacher at your or other in your city AI (Study Centre). Low-effort as instagram reels.</p><h2 id="will-i-have-to-re-upload-tma-if-i-reappear-in-a-exam" tabindex="-1">Will I have to re-upload TMA if i reappear in a exam? <a class="header-anchor" href="#will-i-have-to-re-upload-tma-if-i-reappear-in-a-exam" aria-label="Permalink to &quot;Will I have to re-upload TMA if i reappear in a exam?&quot;">​</a></h2><p>Ans: No TMA is to be submitted only ones, the marks will be carried forward.</p><h2 id="how-to-make-front-page-what-info-should-be-written-on-it" tabindex="-1">How to make front page? What Info should be written on it? <a class="header-anchor" href="#how-to-make-front-page-what-info-should-be-written-on-it" aria-label="Permalink to &quot;How to make front page? What Info should be written on it?&quot;">​</a></h2><p>Ans: There are 3 ways you can make it:</p><ol><li>Just write the info before the answers start.</li><li>Use canva to make and fill it then use a pdf editor to place it before the answers start.</li><li>Use per-made front page from the internet and take print out of it write your info on it. Remember to scan it before the answers start.</li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>I (Author) used the 1st method. Regardless of what you do it won&#39;t effect on your marks.</p></div><p>The following info should be written Your name, Enrollment number, Subject name &amp; sebject code, Medium of study (not required for language subjects), AI name and AI code.</p><h2 id="what-grades-does-nios-have-ia-it-different-from-cbse-or-other-boards" tabindex="-1">What grades does NIOS have ia it different from CBSE or other boards <a class="header-anchor" href="#what-grades-does-nios-have-ia-it-different-from-cbse-or-other-boards" aria-label="Permalink to &quot;What grades does NIOS have ia it different from CBSE or other boards&quot;">​</a></h2><p>There&#39;s no 11th in NIOS, but the syllabus of 11th &amp; 12th are mixed for one grade and one textbook called Sr.Secondary (treated as 12th standard), similarly 9th and 10th are integrated.</p><h2 id="how-does-the-marking-system-and-passing-marks-work-in-nios" tabindex="-1">How does the marking system and Passing Marks work in NIOS? <a class="header-anchor" href="#how-does-the-marking-system-and-passing-marks-work-in-nios" aria-label="Permalink to &quot;How does the marking system and Passing Marks work in NIOS?&quot;">​</a></h2><p>First Max marks for all subjects is <strong>100</strong>.</p><ul><li>For Sec (10th) you need 33% in both Theory <strong>or</strong> Practical e.g., let&#39;s say in Maths (211) you get 25 in Theory and 8 in Practical total 33 = you passed.</li><li>For Sr.Sec (12th) you need 33% of max marks in both Theory <strong>and</strong> Practical (if the subject doesn&#39;t have Practical then it&#39;s just 33% of Theroy)</li></ul><p>All conditions:</p><ol><li>Let&#39;s say in Physics you get 25 in Theory and 6 in Practical = failed in Theory (SYT)</li><li>Let&#39;s say in Physics you get 26 in Theory and 4 in Practical = failed in Practical (SYP)</li><li>Let&#39;s say in Physics you get 26 in Theory and 6 in Practical = Passed in the subject (P)</li><li>let&#39;s say in Physics you get 25 in Theory and 4 in Practical = failed in the subject (SYC)</li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Please don&#39;t include TMA in your Calculations.</p></div><p>⚙️ NIOS follows a unique marking scheme where Tutor Marked Assignments (TMAs) contribute 20% of theory marks and the final theory marks are adjusted accordingly.</p><p>⚙️<strong>Marking Scheme for Practical Subjects (e.g., Physics, Chemistry, Biology, Library and info sci)</strong> :</p><table tabindex="0"><thead><tr><th style="text-align:left;">COMPONENT</th><th style="text-align:left;">WEIGHTAGE</th><th style="text-align:left;">DISTRIBUTION</th></tr></thead><tbody><tr><td style="text-align:left;">PRACTICAL</td><td style="text-align:left;">20</td><td style="text-align:left;">10 (FA) + 10 (SA)</td></tr><tr><td style="text-align:left;">THEORY</td><td style="text-align:left;">80</td><td style="text-align:left;">16 (TMA) + 64 ( EXAM)</td></tr></tbody></table><p><strong>Adjustment of marks</strong>:</p><ul><li>📐 80/80 in the theory exam --- gets adjusted to 64/64 in the marksheet.</li><li>📐 16/20 in TMA --- gets adjusted to 13/16 in the marksheet.</li></ul><blockquote><p>[!WARRING] Practical marks remains unchanged.</p></blockquote><p>Therefore Final Marks: TMA (16) + Theory (64) + Practical (20) = 100/100</p><p>⚙️ <strong>Marking Scheme for Non-Practical Subjects (e.g., Maths, English, History)</strong>:</p><table tabindex="0"><thead><tr><th style="text-align:left;">COMPONENT</th><th style="text-align:left;">WEIGHTAGE</th><th style="text-align:left;">DISTRIBUTION</th></tr></thead><tbody><tr><td style="text-align:left;">PRACTICAL</td><td style="text-align:left;">-</td><td style="text-align:left;">-</td></tr><tr><td style="text-align:left;">THEORY</td><td style="text-align:left;">100</td><td style="text-align:left;">20 (TMAs) + 80 (Theory/final exam)</td></tr><tr><td style="text-align:left;">🧰 <strong>Adjustment of marks</strong>:</td><td style="text-align:left;"></td><td style="text-align:left;"></td></tr></tbody></table><ul><li>📐100/100 in theory -&gt; gets adjusted to 80/80 in the marksheet</li><li>📐18/20 in TMA -&gt; remains 18/20 in the marksheet (doesn&#39;t change)</li></ul><p>Therefore Final Marks: TMA (20) + Theory (80) = 100/100</p><p>⚙️<strong>Specific Case: Subjects with Different Practical Weightage</strong>:</p><p>🧰 Some subjects have higher practical marks, which changes the theory and TMA weightage. For Example Painting (332)🎨:</p><table tabindex="0"><thead><tr><th style="text-align:left;">COMPONENT</th><th style="text-align:left;">WEIGHTAGE</th><th style="text-align:left;">DISTRIBUTION</th></tr></thead><tbody><tr><td style="text-align:left;">PRACTICAL</td><td style="text-align:left;">60</td><td style="text-align:left;">30 (FA) + 30(SA)</td></tr><tr><td style="text-align:left;">THEORY</td><td style="text-align:left;">40</td><td style="text-align:left;">8 (TMA) + 32 ( EXAM)</td></tr></tbody></table><p>🧰 <strong>Adjustment of marks for 🎨Painting</strong> (332):</p><ul><li>📐40/40 in the theory exam -&gt; gets adjusted to 32/32 in the marksheet.</li><li>📐10/20 in TMAs -&gt; gets adjusted to 4/8 in the marksheet.</li></ul><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Practical marks remain unchanged.</p></div><p>Therefore final Marks: TMA (8) + Theory (32) + Practical (60) = 100/100</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>Since STREAM 2, 3, and 4 students don&#39;t have TMAs, these adjustments aren&#39;t for them, their theory and practical marks ---are same as given during exam/on the paper</strong></p></div><p>Sec (10th)</p><table tabindex="0"><thead><tr><th>Sub Code</th><th>Th (Max)</th><th>Pr (Max)</th><th>TMA (Max)</th><th>Tol (Max)</th><th>Pass Marks (Th+Pr)</th><th>Pass Marks (Tol)</th></tr></thead><tbody><tr><td>All Theory Subjects</td><td>80</td><td>-</td><td>20</td><td>100</td><td>26</td><td>26</td></tr><tr><td>211, 212, 216</td><td>68</td><td>15</td><td>17</td><td>100</td><td>27</td><td>27</td></tr><tr><td>229, 230, 242, 243</td><td>40</td><td>60</td><td>08</td><td>100</td><td>30</td><td>30</td></tr></tbody></table><p>Sr.Sec (12th)</p><table tabindex="0"><thead><tr><th>Sub Code</th><th>Th (Max)</th><th>Pr (Max)</th><th>TMA (Max)</th><th>Tol (Max)</th><th>Th (Pass)</th><th>Pr (Pass)</th></tr></thead><tbody><tr><td>All Theory</td><td>80</td><td>-</td><td>20</td><td>100</td><td>26</td><td>-</td></tr><tr><td>330</td><td>48</td><td>40</td><td>12</td><td>100</td><td>16</td><td>13</td></tr><tr><td>336</td><td>32</td><td>60</td><td>08</td><td>100</td><td>11</td><td>20</td></tr></tbody></table><hr><p><strong>PCP and study centre related FAQs</strong></p><h2 id="which-pcp-is-important-only-for-stream-1" tabindex="-1">Which PCP is important? (Only for Stream 1) <a class="header-anchor" href="#which-pcp-is-important-only-for-stream-1" aria-label="Permalink to &quot;Which PCP is important? (Only for Stream 1)&quot;">​</a></h2><p>Ans: The first PCP in December-November (block 1) June-July (block 2) doesn&#39;t carry any marks. FA PCP Carries <strong>50% weightage of Practicals</strong> <a href="/wiki/Exams-Assignments.html#pcp-personal-contact-programme">Read More...</a></p><h2 id="what-do-i-do-if-my-ai-study-centre-is-closed-or-is-no-longer-affiliated-with-nios" tabindex="-1">What do I do if my AI (Study Centre) is closed or is no longer affiliated with NIOS? <a class="header-anchor" href="#what-do-i-do-if-my-ai-study-centre-is-closed-or-is-no-longer-affiliated-with-nios" aria-label="Permalink to &quot;What do I do if my AI (Study Centre) is closed or is no longer affiliated with NIOS?&quot;">​</a></h2><p>Ans: First, chill it’s not a big deal if this has happened to you. Let’s confirm:</p><ol><li><strong>Log on to your dashboard:</strong><br> Scroll down and click on the <code>👁️ View</code> button. At the top, you’ll see “PCP details 2021-22” (ignore that it’s a bug). There should be a table below. By the way, these PCPs are the non-important ones (i.e., 30 classes). If you see “No record found,” that means your study centre is not affiliated with NIOS. <em>How do you know? Because I&#39;m God—yes.</em></li><li><strong>Visit the centre in person.</strong></li><li><strong>Call your regional office and ask them.</strong></li></ol><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p><a href="https://web.archive.org/web/20220216190435/https://sdmis.nios.ac.in/home/regional-center" target="_blank" rel="noreferrer">Click here to view the phone number</a></p></div><p><strong>Why don’t they conduct PCP?</strong></p><p>They’re overworked and busy with CBSE responsibilities.</p><p><strong>What can I do now?</strong></p><p>You need to prepare for your practicals and record book/practical file on your own. If you don’t understand something, just visit <a href="https://www.reddit.com/r/NIOS_Students" target="_blank" rel="noreferrer">Reddit</a> or <a href="/wiki/howto-rec-book.html">read this</a>. You don’t have to do anything else—your Regional Centre has a record of inactive study centres. Now, if your study centre does not conduct FA PCP, or if your study centre is closed and the other centre does not conduct PCP classes either, in most cases they will give you the FA PCP marks.</p><h2 id="what-is-the-count-of-pcp-classes" tabindex="-1">What is the count of PCP classes? <a class="header-anchor" href="#what-is-the-count-of-pcp-classes" aria-label="Permalink to &quot;What is the count of PCP classes?&quot;">​</a></h2><ul><li>Orientation = 1 per Student/Learner <a href="https://www.youtube.com/watch?v=QQTmBiF6L0s&amp;t=2625s" target="_blank" rel="noreferrer">Source</a> Time code 43:43.</li><li>PCP = 30 per Student Source? This is the interpretation, but can&#39;t find any official sources but it&#39;s a fact.</li><li>FA PCP = 05 per <a href="https://nios-students.pages.dev/wiki/pr.html#:~:text=Which%20subject%20has%20practical%3F%20Ans%3A%20Please%20view%20the%20table%20below%3A" target="_blank" rel="noreferrer">Practical subject</a> source? This is the interpretation, but can&#39;t find any official sources but it&#39;s a fact. <s>- <a href="https://rcpune.nios.ac.in/personal-contact-program.html" target="_blank" rel="noreferrer">missinfo</a> ^(The 15 classes of PCP compulsory part is not true , PCP are not compulsory , just FA PCP is compulsory as they carry 50% marks of practical).</s></li></ul><h2 id="where-to-find-info-on-obe" tabindex="-1">Where to find info on OBE <a class="header-anchor" href="#where-to-find-info-on-obe" aria-label="Permalink to &quot;Where to find info on OBE&quot;">​</a></h2><p>The OBE Programme covers elementary level education and is offered at three levels:</p><ul><li>OBE level A: equivalent to class I-III</li><li>OBE level B: equivalent to class IV-V</li><li>OBE level C: equivalent to class VI-VIII</li></ul><p>🔸For more info - <strong>🔻Academic prospectus for OBE:</strong></p><ul><li><p><a href="https://www.nios.ac.in/departmentsunits/academic/open-basic-education-(obe).aspx" target="_blank" rel="noreferrer">OBE link 1</a></p></li><li><p><a href="https://www.nios.ac.in/media/documents/prospectus/OBE_Prospectus/OBE_Adult_Prospectus_2024-25_Final.pdf" target="_blank" rel="noreferrer">OBE link 2</a></p></li><li><p><a href="https://www.nios.ac.in/media/documents/prospectus/OBE_Prospectus/OBE_Children_Prospectus_2024-25_Final.pdf" target="_blank" rel="noreferrer">OBE link 3</a></p></li><li><p><a href="https://www.google.com/url?sa=t&amp;source=web&amp;rct=j&amp;opi=89978449&amp;url=https://nios.ac.in/media/documents/accr/obeguide.pdf&amp;ved=2ahUKEwjA7932taCMAxWbRmwGHQ8eOMMQFnoECFYQAQ&amp;usg=AOvVaw3j4MwSNfeyEGBv45XiiR0e" target="_blank" rel="noreferrer">OBE link 4</a></p></li></ul><p><strong>Public examination FAQs</strong></p><h2 id="what-is-the-gap-this-is-for-freshers-of-senior-secondary-12th-only" tabindex="-1">What is the gap? (this is for freshers of <strong>Senior Secondary (12th)</strong> only) <a class="header-anchor" href="#what-is-the-gap-this-is-for-freshers-of-senior-secondary-12th-only" aria-label="Permalink to &quot;What is the gap? (this is for freshers of **Senior Secondary (12th)** only)&quot;">​</a></h2><p>Ans: There must be at least a 2 year gap between passing 10th grade and passing 12th.</p><ul><li>If you passed 10th grade (April 2024, or October 2024) and are taking 12th grade exams in April-May 2025, you can only pay exam fees for up to 4 subjects. (You can 4 sebjects or 1 sebject or not give any sebject)</li><li>If you pay for more than 4 subjects and don’t meet the 2 year gap, your results won’t be declared.</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>If you finish your exams in the second year NIOS will give your result documents after you give all sebjects i.e. after the second exam results are declared.</p></div><h2 id="can-i-change-exam-centre-be-changed-pe" tabindex="-1">Can I change exam centre be changed (PE)? <a class="header-anchor" href="#can-i-change-exam-centre-be-changed-pe" aria-label="Permalink to &quot;Can I change exam centre be changed (PE)?&quot;">​</a></h2><p>Ans: Yes there is a e-service that however, it just returns &quot; Change of exam center is now closed.&quot; YOU can&#39;t change the exam centre.</p><h2 id="where-are-the-practical-examination-held" tabindex="-1">Where are the practical examination held? <a class="header-anchor" href="#where-are-the-practical-examination-held" aria-label="Permalink to &quot;Where are the practical examination held?&quot;">​</a></h2><p>Ans: Practical examinations for Public examinations are normally held in the respective AIs, where the learner gets enrolled. If your AI/Study Centre is inactive or closed another centre will be allocated to you.</p><h2 id="will-my-marks-be-carried-forward" tabindex="-1">Will my marks be carried forward? <a class="header-anchor" href="#will-my-marks-be-carried-forward" aria-label="Permalink to &quot;Will my marks be carried forward?&quot;">​</a></h2><p>Ans: At Sr.Secondary level (12th), if one fails in theory but passes in practical, do they have to appear in practical again and vica versa. If learner passes in practical but fails in the theory of a subject, his/her practical awards/marks will be retained and can appear in Theory Examination only. In case the learner re-appears in both theory and practical, then the <strong>best combination of marks</strong> will be retained.</p><h2 id="how-to-deal-with-stress" tabindex="-1">How to deal with stress <a class="header-anchor" href="#how-to-deal-with-stress" aria-label="Permalink to &quot;How to deal with stress&quot;">​</a></h2><p><a href="https://nios.ac.in/faq/handling-examination-related-stress" target="_blank" rel="noreferrer">Click here (www.nios.ac.in)</a></p><h2 id="are-calculators-allowed-in-examination-applicable-in-every-single-examination" tabindex="-1">Are calculators allowed in examination? (Applicable in every single examination.) <a class="header-anchor" href="#are-calculators-allowed-in-examination-applicable-in-every-single-examination" aria-label="Permalink to &quot;Are calculators allowed in examination? (Applicable in every single examination.)&quot;">​</a></h2>',89),e("p",{"F44989A0-83EC-4717-94FC-AED59EA79440":""},[a("Ans: No, calculators not allowed. Please refer the picture from "),e("em",null,"Guidelines for Centre Superintendents for Theory Examinations"),e("img",{src:"https://github.com/user-attachments/assets/584bd151-4700-40bd-8dad-9f1ee46d4938",alt:"{F44989A0-83EC-4717-94FC-AED59EA79440}"})],-1),t('<div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>&quot;However, in the case of learners with disabilities&quot; They&#39;re talking about computers/Typewriters here.</p></div><h2 id="are-nios-exam-centers-different-from-your-study-centre" tabindex="-1">Are NIOS exam centers different from your study Centre? <a class="header-anchor" href="#are-nios-exam-centers-different-from-your-study-centre" aria-label="Permalink to &quot;Are NIOS exam centers different from your study Centre?&quot;">​</a></h2><p>Ans: Yes, the exam centre for Theory examination is different from Study Centre which is for FA and SA.</p><h2 id="do-you-get-your-exam-centre-randomly" tabindex="-1">Do you get your exam centre randomly? <a class="header-anchor" href="#do-you-get-your-exam-centre-randomly" aria-label="Permalink to &quot;Do you get your exam centre randomly?&quot;">​</a></h2><p>Ans: No, they chose the centre based on your location.</p><p><strong>On Demand exam related FAQs</strong></p><h2 id="are-questions-asked-from-bifurcation-or-the-full-book-in-ode" tabindex="-1">Are Questions asked from bifurcation or the full book in ODE? <a class="header-anchor" href="#are-questions-asked-from-bifurcation-or-the-full-book-in-ode" aria-label="Permalink to &quot;Are Questions asked from bifurcation or the full book in ODE?&quot;">​</a></h2><p>Ans: Only public Exam chapters, no TMA chapters! Only public exam chapters, since NIOS is lazy asf so sometimes they mistakenly add 2 to 3 questions from TMA chapters! <a href="https://www.reddit.com/r/NIOS_Students/s/GNH9m0GrRi" target="_blank" rel="noreferrer">this</a> reddit post. The <a href="https://www.reddit.com/r/NoStupidQuestions/comments/15tmb2s/what_does_aita_and_op_mean_on_reddit/" target="_blank" rel="noreferrer">OP</a> filed for a RTI</p><p><strong>for which the answer is given below:</strong></p><img src="https://cdn.jsdelivr.net/gh/nios-students/docs@master/wiki/assets/rti-response-says-tma-chapters-are-not-asked-in-ode-exams-1.webp" alt="RTI-1" width="400"><img src="https://cdn.jsdelivr.net/gh/nios-students/docs@master/wiki/assets/rti-response-says-tma-chapters-are-not-asked-in-ode-exams-2.webp" alt="RIT-2" width="400"><h2 id="what-is-toc-transfer-of-credit" tabindex="-1">What is ToC (Transfer of Credit)? <a class="header-anchor" href="#what-is-toc-transfer-of-credit" aria-label="Permalink to &quot;What is ToC (Transfer of Credit)?&quot;">​</a></h2><p>It allows you to transfer marks from up to 2 previously passed CBSE subjects into your NIOS marksheet. Only available to boardsstudents who failed CBSE and are redoing 3 subjects via ODE.</p><h2 id="can-i-get-a-combined-marksheet-of-my-old-board-and-nios-if-i-passed-overall-but-to-increase-my-percentage" tabindex="-1">Can I get a combined marksheet of my old board and NIOS if I passed overall but to increase my percentage? <a class="header-anchor" href="#can-i-get-a-combined-marksheet-of-my-old-board-and-nios-if-i-passed-overall-but-to-increase-my-percentage" aria-label="Permalink to &quot;Can I get a combined marksheet of my old board and NIOS if I passed overall but to increase my percentage?&quot;">​</a></h2><p>Only failed students using the ToC option can get a combined NIOS marksheet (with 2 ToC subjects + 3 ODE subjects).</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>CBSE-passed students who registered under Dual/Part Enrollment will get a separate mark sheet for the passed subjects.</p></div><h2 id="are-there-practicals-in-ode" tabindex="-1">Are there practicals in ODE? <a class="header-anchor" href="#are-there-practicals-in-ode" aria-label="Permalink to &quot;Are there practicals in ODE?&quot;">​</a></h2><p>Yes, But if the subject has practicals, you must complete both theory and practical exams. (Subjects that has practical Check out this page – Click me!</p><h2 id="can-i-choose-any-exam-center" tabindex="-1">Can I choose any exam center? <a class="header-anchor" href="#can-i-choose-any-exam-center" aria-label="Permalink to &quot;Can I choose any exam center?&quot;">​</a></h2><p>Yes, there are limited options to pick, but centres get booked quickly. Select your exam centre as soon as registration opens.</p><h2 id="when-will-i-get-my-result" tabindex="-1">When Will I Get My Result? <a class="header-anchor" href="#when-will-i-get-my-result" aria-label="Permalink to &quot;When Will I Get My Result?&quot;">​</a></h2><p>You can expect results within 40–50 days after the exam.</p><h2 id="subject-availability-for-ode" tabindex="-1">Subject availability for ODE? <a class="header-anchor" href="#subject-availability-for-ode" aria-label="Permalink to &quot;Subject availability for ODE?&quot;">​</a></h2><h2 id="_12th-sr-sec" tabindex="-1">12th (Sr.Sec) <a class="header-anchor" href="#_12th-sr-sec" aria-label="Permalink to &quot;12th (Sr.Sec)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Subject Name and Code</th></tr></thead><tbody><tr><td>Physics (312)</td></tr><tr><td>English (302)</td></tr><tr><td>Business Studies (319)</td></tr><tr><td>Economics (318)</td></tr><tr><td>Political Science (317)</td></tr><tr><td>Sanskrit (309)</td></tr><tr><td>Mathematics (311)</td></tr><tr><td>History (315)</td></tr><tr><td>Biology (314)</td></tr><tr><td>Geography (316)</td></tr><tr><td>Psychology (328)</td></tr><tr><td>Painting (332)</td></tr><tr><td>Environmental Science (333)</td></tr><tr><td>Data Entry Operations (336)</td></tr><tr><td>Chemistry (313)</td></tr></tbody></table><h2 id="_10th-sec" tabindex="-1">10th (Sec) <a class="header-anchor" href="#_10th-sec" aria-label="Permalink to &quot;10th (Sec)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Subject Name and Code</th></tr></thead><tbody><tr><td>Hindi (201)</td></tr><tr><td>Mathematics (211)</td></tr><tr><td>Painting (225)</td></tr><tr><td>Sanskrit (209)</td></tr><tr><td>English (202)</td></tr><tr><td>Science &amp; Technology (212)</td></tr><tr><td>Data Entry Operations (229)</td></tr><tr><td>Social Science (213)</td></tr><tr><td>Economics (214)</td></tr><tr><td>Business Studies (215)</td></tr><tr><td>Home Science (216)</td></tr><tr><td>Psychology (222)</td></tr><tr><td>Indian Culture &amp; Heritage (223)</td></tr><tr><td>Accountancy (224)</td></tr><tr><td>Bharatiya Darshan (247)</td></tr><tr><td>Sanskrit Sahitya (248)</td></tr></tbody></table><p><strong>Technical issues and other miscellaneous FAQs</strong></p><h2 id="what-are-the-official-video-resources" tabindex="-1">What are the official video resources <a class="header-anchor" href="#what-are-the-official-video-resources" aria-label="Permalink to &quot;What are the official video resources&quot;">​</a></h2><p>Related links:</p><ul><li><a href="https://sdmis.nios.ac.in/home/video-gallery" target="_blank" rel="noreferrer">Browse videos</a></li><li><a href="https://sdmis.nios.ac.in/home/lab-practical" target="_blank" rel="noreferrer">Browse lab practicals</a></li><li><a href="https://www.reddit.com/r/Nios_unofficial" target="_blank" rel="noreferrer">Sub</a></li></ul><p>2 YT channels for recorded vids:</p><ul><li><a href="https://youtube.com/@niossecondarycourses" target="_blank" rel="noreferrer">NIOS secondary (10th)</a></li><li><a href="https://youtube.com/@niosseniorsecondarycourses" target="_blank" rel="noreferrer">NIOS Senior Secondary (12th)</a></li></ul><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p><strong>Archived Live Streams from 2019-2024 (August). This channel is now used for events only. <a href="https://youtube.com/@nioslivevideo" target="_blank" rel="noreferrer">NIOS Live Video</a></strong></p></div><p><a href="https://youtube.com/@niosmuktavidyavaniradiovahini" target="_blank" rel="noreferrer">Radio: NIOS Mukta Vidyavani &amp; Radiovahini</a></p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>This channel is used for audio only. Streams from Monday-Friday from 11.00 PM to 3.45 PM (IST)</strong>. Archived audio programs <a href="https://nios.ac.in/audio_files/AG_Sr_Secondary.pdf" target="_blank" rel="noreferrer">12th Sr.Secondary</a> and <a href="https://nios.ac.in/audio_files/AG_Secondary.pdf" target="_blank" rel="noreferrer">10th Secondary</a> <a href="https://nios.ac.in/departmentsunits/media-unittelecast/mukta-vidya-vani-and-community-radio.aspx" target="_blank" rel="noreferrer">Schedule page link (nios.ac.in)</a></p></div><p><strong>Program schedule</strong></p><ul><li>[🔴 <strong>Live</strong>] Community programming from 11.00 PM to 12.00 PM.</li><li>[🔴 <strong>Live</strong>] Secondary (10th) from 12.00 PM to 12.45 PM</li><li>[Per-recorded] from 12.45 PM to 2.00 PM.</li><li>[🔴 <strong>Live</strong>] Senior Secondary (12th) from 2.00 PM to 2.45 PM.</li><li>[🔴 <strong>Live</strong>] Vocational from 3.00 PM to 3.45 PM.</li></ul><p>Video Live streams there are 4 channels:</p><ul><li><a href="https://youtube.com/@ddpmevidyanios17sec" target="_blank" rel="noreferrer">Secondary (10th)</a> <strong>🔴 from 1.00 PM to 2.00 PM (IST)</strong></li><li><a href="https://youtube.com/@ddpmevidyanios18srsec" target="_blank" rel="noreferrer">Senior Secondary (12th)</a> <strong>🔴 from 2.00 PM to 3.00 PM (IST)</strong></li><li><a href="https://youtube.com/@ddpmevidyanios19obeislikt" target="_blank" rel="noreferrer">OBE/ISL</a> <strong>🔴 from 3.00 PM to 4.00 PM (IST)</strong></li><li><a href="https://youtube.com/@niospmevidya20vocational" target="_blank" rel="noreferrer">Vocational</a> <strong>🔴 from 4.00 PM to 5.00 PM (IST)</strong></li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Follow them on <a href="https://x.com/Niostiw" target="_blank" rel="noreferrer">X</a> or <a href="https://discord.gg/9QYJ5RtH" target="_blank" rel="noreferrer">here</a> for daily schedule of live streams. Most videos/explanations are just people reading PPTs. Live Streams are cancelled sometimes, but we can&#39;t do anything. about it sadly.</p></div><h2 id="what-is-abcid-is-that-required" tabindex="-1">What is ABCID? Is that required? <a class="header-anchor" href="#what-is-abcid-is-that-required" aria-label="Permalink to &quot;What is ABCID? Is that required?&quot;">​</a></h2><p>Ans: ABCID is used to keep track of academic progress. It&#39;s mostly by college going students. No it&#39;s not required however, a popup will be display every time you login.</p><h2 id="how-can-i-reduce-size-of-a-pdf-file" tabindex="-1">How can i reduce size of a pdf file? <a class="header-anchor" href="#how-can-i-reduce-size-of-a-pdf-file" aria-label="Permalink to &quot;How can i reduce size of a pdf file?&quot;">​</a></h2>',44),e("details",{class:"details custom-block"},[e("summary",null,"Show videos"),e("iframe",{width:"560",height:"315",src:"https://www.youtube.com/embed/aHFF2MYb-6I",title:"How To Compress PDF File Size Without Losing Quality - Full Guide",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",referrerpolicy:"strict-origin-when-cross-origin",allowfullscreen:""})],-1),e("div",{class:"note custom-block github-alert"},[e("p",{class:"custom-block-title"},"NOTE"),e("p",null,[e("code",null,"https//ilovepdf.com"),a(" is website so, you can do this on any device which has a web browser and storage for.pdf file.")])],-1),e("h2",{id:"how-to-open-zip-rar-file",tabindex:"-1"},[a("How to open .zip/.rar file? "),e("a",{class:"header-anchor",href:"#how-to-open-zip-rar-file","aria-label":'Permalink to "How to open .zip/.rar file?"'},"​")],-1),e("p",null,"Click on the videos",-1),e("details",{class:"details custom-block"},[e("summary",null,"Show videos"),e("iframe",{width:"560",height:"315",src:"https://www.youtube.com/embed/nXAYWwiDvc8",title:"Windows 7  - How to extract  a zip file.",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",referrerpolicy:"strict-origin-when-cross-origin",allowfullscreen:""}),e("iframe",{width:"560",height:"315",src:"https://www.youtube.com/embed/f1Iw9P_QQsc",title:"How To Extract Zip Files & Folders in Windows 11",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",referrerpolicy:"strict-origin-when-cross-origin",allowfullscreen:""}),e("iframe",{width:"560",height:"315",src:"https://www.youtube.com/embed/RyhkTF2jt90",title:"How to Extract ZIP Files on Android !",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",referrerpolicy:"strict-origin-when-cross-origin",allowfullscreen:""}),e("iframe",{width:"560",height:"315",src:"https://www.youtube.com/embed/TFcBqqDGLr4",title:"How to Open / Extract RAR File on iPhone or iPad",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",referrerpolicy:"strict-origin-when-cross-origin",allowfullscreen:""}),e("iframe",{width:"560",height:"315",src:"https://www.youtube.com/embed/J8Mzm01rpbc",title:"How to Zip & Unzip files on Chromebook",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",referrerpolicy:"strict-origin-when-cross-origin",allowfullscreen:""}),e("iframe",{width:"560",height:"315",src:"https://www.youtube.com/embed/N236GiRolXU",title:"How To Unzip Files Online [Simple Guide]",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",referrerpolicy:"strict-origin-when-cross-origin",allowfullscreen:""})],-1),t('<h2 id="why-is-the-year-wrong" tabindex="-1">Why is the year wrong? <a class="header-anchor" href="#why-is-the-year-wrong" aria-label="Permalink to &quot;Why is the year wrong?&quot;">​</a></h2><p><img src="https://github.com/user-attachments/assets/2f483933-f27c-45ec-beaa-aaec22df0662" alt="WhatsApp Image 2025-06-14 at 23 11 46_e8012d93"> It’s a well known bug. NIOS HQ are lazy or busy with building a AI.</p><h2 id="what-is-the-two-vocational-subjects-rule" tabindex="-1">What is the two vocational Subjects rule? <a class="header-anchor" href="#what-is-the-two-vocational-subjects-rule" aria-label="Permalink to &quot;What is the two vocational Subjects rule?&quot;">​</a></h2><p><code>XXXX</code> will be displayed in your result if you have TWO (2) Vocational subjects from given below the table given:</p><hr><table tabindex="0"><thead><tr><th>10th Vocational Subjects</th><th>12th Vocational Subjects</th></tr></thead><tbody><tr><td>1. Data Entry Operations (229)</td><td>1. Data Entry Operations (336)</td></tr><tr><td>2. Entrepreneurship (249)</td><td>2. Tourism (337)</td></tr><tr><td>3. Cutting and Tailoring (605)</td><td>3. House-Keeping (356)</td></tr><tr><td>4. Dress Making (606)</td><td>4. Catering Management (357)</td></tr><tr><td>5. Basic Computing (608)</td><td>5. Food Processing (358)</td></tr><tr><td>6. Beauty Culture and Hair Care (612)</td><td>6. Hotel Front Office Operations (360)</td></tr><tr><td>7. Desk Top Publishing (613)</td><td>7. Preservation of Fruits and Vegetables (363)</td></tr><tr><td>8. Yoga (614)</td><td>8. Physical Education and Yog (373)</td></tr><tr><td>9. Indian Embroidery (628)</td><td>9. Early Childhood Care and Education (376)</td></tr><tr><td>10. Beauty Therapy (640)</td><td>10. Web Designing and Development (622)</td></tr><tr><td>11. Hair Care and Styling (641)</td><td>11. Computer &amp; Office Applications (631)</td></tr><tr><td>12. Hand and Foot Care (642)</td><td>12. Data Entry Operations (632)</td></tr><tr><td>-</td><td>13. IT Essentials: PC Hardware and Software (651)</td></tr><tr><td></td><td>14. Web Development (660)</td></tr><tr><td></td><td>15. CRM Domestic Voice (661)</td></tr><tr><td></td><td>16. Computer Hardware Assembly &amp; Maintenance (663)</td></tr><tr><td></td><td>17. Yoga Assistant (667)</td></tr></tbody></table><hr><h2 id="is-manish-verma-legit" tabindex="-1">Is Manish Verma legit? <a class="header-anchor" href="#is-manish-verma-legit" aria-label="Permalink to &quot;Is Manish Verma legit?&quot;">​</a></h2><p>Short answer NO. Long answer As per the information on their website about section &quot;This website is not <strong>associated with NIOS</strong>, For official website of NIOS visit – <a href="https://www.nios.ac.in/" target="_blank" rel="noreferrer">https://www.nios.ac.in/</a>&quot; This could be in the context of: &quot;Hey, we are a CSC and Study Centre. You can find information about our courses, guides, and other stuff, but our website isn&#39;t the official website of NIOS. So, is this paragraph garbage? No, but it makes you think, &quot;Why would a CSC <strong>and</strong> Study Centre say this isn’t the main website instead of just giving a link to it?&quot; What is a CSC/Facilitation Centre, and what are its functions?</p><p>In general:</p><ul><li>Common Services Centres (CSCs) are access points for delivering Government-to-Citizen (G2C) e-services within the reach of citizens by creating physical service delivery ICT infrastructure.</li></ul><p>In the context of NIOS:</p><ul><li>They help learners with admission, payment of exam fees, and re-booking.</li></ul><p>But where are educational services such as TMA, Practicals, books, Question Banks, and other resources <em><strong>not</strong></em> mentioned in the above paragraph?</p><p>What is a Study Centre/AI, and what are its functions?</p><ul><li>Helping learners with admission and payment of exam fees.</li><li>Checking TMAs and uploading marks.</li><li>Conducting PCP, FA PCP, and practical exams.</li></ul><blockquote><p>Does this centre conduct these activities? NO</p></blockquote><blockquote><p>Why would NIOS want students <em><strong>not</strong></em> to do their work, such as TMAs and practical record books/files?</p></blockquote><h2 id="what-is-optional-module-do-i-need-to-study-it" tabindex="-1">What is Optional module? Do i need to study it? <a class="header-anchor" href="#what-is-optional-module-do-i-need-to-study-it" aria-label="Permalink to &quot;What is Optional module? Do i need to study it?&quot;">​</a></h2><p>Many subjects such as English, Business Studies, Home Science, and more are divided into modules, one of which is optional.</p><ul><li>How Optional Modules Work in NIOS</li></ul><p>The syllabus is structured as follows:</p><ul><li>Modules from so and so - This is the core module and is compulsory.</li><li>Optional module – This is the optional module, and students must choose between Module A and Module B. You are not supposed to do both Modules in the exam you choose either A or B.</li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>there is no checkbox for you to tick, whenever a question is asked from Optional module you can mention which Module you have picked e.g., <strong>3 Ans (optional module A)</strong>, additionally you can also write it before starting a Section e.g., <strong>Section-A (optional module A)</strong>.</p></div><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Important You are expected to answer questions only from one Module A or B. Do <strong>NOT</strong> attempt questions from both module A and module B doing so could result in marks being deducted or responses being ignored.</p></div><h2 id="where-is-find-whatever-i-m-looking-for" tabindex="-1">Where is find whatever I&#39;m looking for? <a class="header-anchor" href="#where-is-find-whatever-i-m-looking-for" aria-label="Permalink to &quot;Where is find whatever I&#39;m looking for?&quot;">​</a></h2><ul><li>PCP (non compulsory) Hall Ticket <a href="https://sdmis.nios.ac.in/search/pcp-hall-ticket" target="_blank" rel="noreferrer">1</a></li><li>FA PCP Hall Ticket <a href="https://sdmis.nios.ac.in/search/fa-hall-ticket" target="_blank" rel="noreferrer">2</a></li><li>Practical (SA) and Theory Exam Hall Ticket <strong>Pubic exams only</strong> <a href="https://sdmis.nios.ac.in/search/hall-ticket" target="_blank" rel="noreferrer">3</a></li><li>View FA/SA Marks Awarded or not <a href="https://exams.nios.ac.in/auth/view-student-formative-assessment" target="_blank" rel="noreferrer">4</a></li><li>Notifications <a href="https://www.nios.ac.in/notice-boardoffice-order/for-all-orders-office-orders.aspx" target="_blank" rel="noreferrer">5</a> / <a href="https://sdmis.nios.ac.in/registration/home-notifications" target="_blank" rel="noreferrer">6</a> Required to logout*</li><li>Results Website <a href="https://results.nios.ac.in" target="_blank" rel="noreferrer">7</a></li><li>ODE Hall Ticket <a href="https://sdmis.nios.ac.in/registration/hall-ticket" target="_blank" rel="noreferrer">8</a> You <strong>Must</strong> re-book a seat and log in*</li><li>X NIOS HQ <a href="https://x.com/niostwit" target="_blank" rel="noreferrer">9</a></li><li>Stream 1 Admission <a href="https://sdmis.nios.ac.in/registration/index?stream_code=1&amp;block_code=11" target="_blank" rel="noreferrer">10</a></li><li>Stream 2 Admission <a href="https://sdmis.nios.ac.in/registration/index?stream_code=2&amp;block_code=21" target="_blank" rel="noreferrer">11</a></li><li>OBE (CLASS 1 TO 8) Registration <a href="https://sdmis.nios.ac.in/modules/obe-registration/index?stream_code=5&amp;block_code=51" target="_blank" rel="noreferrer">12</a></li><li>Admission Status <a href="https://sdmis.nios.ac.in/registration/check-admission-status" target="_blank" rel="noreferrer">13</a></li><li>Student Dashboard <a href="https://sdmis.nios.ac.in/home/dashboard" target="_blank" rel="noreferrer">14</a></li></ul><h2 id="how-to-get-a-character-certificate-from-nios" tabindex="-1">How to Get a Character Certificate from NIOS? <a class="header-anchor" href="#how-to-get-a-character-certificate-from-nios" aria-label="Permalink to &quot;How to Get a Character Certificate from NIOS?&quot;">​</a></h2><p>If you&#39;re a <a href="https://nios-students.pages.dev/wiki/Glossary.html#:~:text=NIOS%3A%20National%20Institute%20of%20Open%20Schooling.%20Link%20to%20section" target="_blank" rel="noreferrer">NIOS</a> student and applying to a college or government institution that’s asking for a <strong>Character certificate</strong>, you’ve probably run into a wall. Here&#39;s the truth — and how to deal with it:</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>NIOS does not issue character certificates. Neither does CBSE — because it&#39;s not the board’s job. In traditional schools, these certificates are issued by the school Principal based on your conduct, attendance, and overall behavior.</p></div><p>NIOS is an open board, so there&#39;s usually no regular school or daily interaction. That’s why your study centre won’t give you one and frankly, it doesn’t make sense for them to.</p><p><strong>If a college or university asks?</strong></p><p>If you&#39;re applying to a State or Central govt. Clg/uni, and they ask for a Character Certificate, just tell them you studied under an open board (NIOS). Most institutions will understand this once you clarify. But — if they still insist on a certificate, here are your options:</p><ul><li>Ask your study centre If they’re cooperative and you had some level of interaction (e.g., attending PCP classes), they might issue a certificate.</li><li>Visit your local police station Many students get a character certificate issued by the police after a basic background check. It’s official and widely accepted.</li><li>Create a character affidavit through a notary If the above don’t work out, go to a lawyer or notary and get an affidavit declaring your good character. This is a legal workaround and often accepted when no official certificate is available.</li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Always be honest about studying from NIOS. It’s a recognized and valid board under the MoE, Most institutions just need clarity and once you explain, they’ll often accept alternative documentation. Special thanks go <a href="https://www.reddit.com/user/a3ryk" target="_blank" rel="noreferrer">Aeryk</a> for allowing us to use this.</p></div><p><strong>Fees related FAQs</strong></p><h2 id="i-gave-public-exam-now-i-wanna-register-for-the-upcoming-public-exam-but-it-won-t-let-me-why-is-that" tabindex="-1">I gave Public Exam now i wanna register for the upcoming Public Exam but it won&#39;t let me why is that? <a class="header-anchor" href="#i-gave-public-exam-now-i-wanna-register-for-the-upcoming-public-exam-but-it-won-t-let-me-why-is-that" aria-label="Permalink to &quot;I gave Public Exam now i wanna register for the upcoming Public Exam but it won&#39;t let me why is that?&quot;">​</a></h2><p>Ans: Please wait until results of the exam you gave or paid fees for are released. NIOS will make another schedule for you. It takes two or three weeks after the results are released.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>This is nothing new it&#39;s a norm</strong> <a href="https://whatsapp.com/channel/0029VamKd7w3LdQV8AqlNF1h" target="_blank" rel="noreferrer"><strong>Join our WhatsApp update channel</strong></a></p></div><h2 id="i-paid-addmission-fees-why-should-pay-exam-for-public-exams-fees-only-for-stream-1" tabindex="-1">I paid &quot;Addmission Fees&quot; Why should pay exam for public exams fees? (Only for Stream 1) <a class="header-anchor" href="#i-paid-addmission-fees-why-should-pay-exam-for-public-exams-fees-only-for-stream-1" aria-label="Permalink to &quot;I paid &quot;Addmission Fees&quot; Why should pay exam for public exams fees? (Only for Stream 1)&quot;">​</a></h2><p>Because the fees you paid it beginning was admission into NIOS. It covers your books and PCPs. You <strong>must</strong> to exam fees in order appear in the exam. Btw exam fee includes question paper, answer booklet, fees for teachers who will check your answers, and other miscellaneous expenses.</p><h2 id="what-is-fee-for-exam-and-other-fees" tabindex="-1">What is fee for Exam and other fees? <a class="header-anchor" href="#what-is-fee-for-exam-and-other-fees" aria-label="Permalink to &quot;What is fee for Exam and other fees?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>SN</th><th>Description</th><th>Revised Rates</th></tr></thead><tbody><tr><td>a</td><td>Examination fee per subject</td><td>Rs. 300/- per subject</td></tr><tr><td>b</td><td>Additional fee for subjects having practical components</td><td>Rs. 150/- per practical subject</td></tr><tr><td>c</td><td>Late fee (for First 10 days)</td><td>Rs. 150/- per subject</td></tr><tr><td>d</td><td>Consolidated late fee for next 10 days after late fee</td><td>Rs. 1600/- consolidated</td></tr><tr><td>e</td><td>Re-checking of answer books</td><td>Rs. 400/- per subject</td></tr><tr><td>f</td><td>Re-evaluation of answer books</td><td>Rs. 1000/- per subject</td></tr></tbody></table><hr><table tabindex="0"><thead><tr><th>SN</th><th>Description</th><th>Revised Rates</th></tr></thead><tbody><tr><td>a</td><td>Examination fee per subject</td><td>Rs. 600/- per subject</td></tr><tr><td>b</td><td>Additional fee for subjects having practical components</td><td>Rs. 250/- per practical subject</td></tr><tr><td>c</td><td>Re-evaluation of answer books</td><td>Rs. 1200/- per subject</td></tr></tbody></table><hr><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Exta ₹70 will be added for Online fee processing.</p></div>',47)]))}const b=o(n,[["render",l]]);export{f as __pageData,b as default};
